{
 "command": "ls scripts && sed -n 1,200p scripts/reconcile_ledger.py",
 "description": "List scripts and view reconcile script"
}

{
 "command": "python3 scripts/reconcile_ledger.py --month 2026-09; echo \"exit=$?\"; head -5 var/ledger/2026-09.csv; wc -l var/ledger/2026-09.csv",
 "description": "Run reconciliation and inspect export"
}

{
 "command": "python3 scripts/reconcile_ledger.py --month 2026-09 --format v1; echo \"exit=$?\"; cat var/ledger/2026-09.csv; ls var/ledger",
 "description": "Rerun reconciliation with v1 format"
}
